    print("===", fn, "===")
    types = {}
    cur_type = None
    cur_z = 0.0
    support_coords = []
    overhang_coords = []
    with open(fn) as f:
        for line in f:
            if line.startswith(";TYPE:"):
                cur_type = line.strip().split(":", 1)[1]
                types[cur_type] = types.get(cur_type, 0) + 1
            elif line.startswith(";Z:"):
