// Creates an organic snake body slice at position x with half-width w, height h, and length dx
// Flat bottom on Z = 0, gently curved lower flanks, arched back with dorsal keel
module snake_cross_section(x, w, h, dx = 0.8) {
    // Bottom flat width is 72% of max width for excellent bed adhesion and zero steep overhang
    w_flat = w * 0.72;
    z_mid  = h * 0.42;
    r_top  = w * 0.58;

    translate([x, 0, 0]) {
        hull() {
            // Flat belly plate on build plate Z = 0
            translate([-dx/2, -w_flat, 0])
                cube([dx, 2 * w_flat, 1.0]);

            // Mid-flank widest part (slope from w_flat at z=0 to w at z_mid is >= 55 deg from horizontal)
            translate([-dx/2, -w, z_mid])
                cube([dx, 2 * w, 0.8]);

            // Upper dorsal arch
            translate([0, 0, h - r_top * 0.65])
                rotate([0, 90, 0])
                    cylinder(r = r_top, h = dx, center = true);

            // Dorsal ridge keel at the crown
            translate([-dx/2, -w * 0.16, h - 0.6])
                cube([dx, w * 0.32, 0.6]);
        }
    }
}

// Sculpted dorsal scales and lateral rib grooves added/carved on a body segment
module body_scale_details(x_start, x_end, w_front, w_rear, h_front, h_rear) {
    seg_len = x_end - x_start;
    // 3 overlapping dorsal diamond scale crests along the top spine
    for (k = [0 : 2]) {
        t  = (k + 0.5) / 3.0;
        xk = x_start + seg_len * (0.20 + 0.60 * t);
        wk = w_front * (1 - t) + w_rear * t;
        hk = h_front * (1 - t) + h_rear * t;

        translate([xk, 0, hk - 0.9]) {
            hull() {
                translate([-2.6, 0, 0])
                    scale([1.0, 0.75, 0.45])
                        cylinder(r1 = wk * 0.36, r2 = wk * 0.12, h = 1.4, $fn = 6);
                translate([1.8, 0, -0.2])
                    scale([1.0, 0.55, 0.35])
                        cylinder(r1 = wk * 0.28, r2 = 0.4, h = 1.2, $fn = 6);
            }
        }
    }
}

// Shallow self-supporting lateral scale V-grooves on left and right flanks
module lateral_scale_grooves(x_start, x_end, w_avg, h_avg) {
    seg_len = x_end - x_start;
    for (side = [-1, 1]) {
        for (k = [-1, 0, 1]) {
            xg = (x_start + x_end) * 0.5 + k * (seg_len * 0.22);
            translate([xg, side * (w_avg + 0.3), h_avg * 0.45])
                rotate([side * 18, 0, -side * 12])
                    rotate([0, 0, 45])
                        cube([0.9, 0.9, h_avg * 0.52], center = true);
        }
    }
}

// ============================================================================
// Part 1: Sculpted Viper/Python Head (parts_1.stl)
// ============================================================================
module part_1_head() {
    j = 0; // Joint 1 at index 0 (x = -45.0)
    jx = joint_x[j];
    jh = joint_h[j];

    difference() {
        union() {
            // Main sculpted head loft from snout_tip_x (-75.0) to Joint 1 (-45.0)
            // Section 1: Snout -> Brow
            hull() {
                // Snout tip at X = -74.2 (rounded front)
                translate([snout_tip_x + 1.2, 0, 0]) {
                    cylinder(r = 4.2, h = 1.2);
                    translate([0, 0, 5.5])
                        cylinder(r1 = 5.2, r2 = 3.6, h = 4.2);
                }
                // Nostril region at X = -70.0
                snake_cross_section(-70.0, 7.6, 12.6, 1.0);
                // Eye / Supraocular brow region at X = -62.5
                snake_cross_section(-62.5, 11.8, 17.2, 1.2);
            }

            // Section 2: Brow -> Broad Temporal Venom Cheeks
            hull() {
                snake_cross_section(-62.5, 11.8, 17.2, 1.2);
                snake_cross_section(-54.5, seg_half_w[0], seg_max_h[0], 1.6);
            }

            // Section 3: Temporal Cheeks -> Neck at Joint 1
            hull() {
                snake_cross_section(-54.5, seg_half_w[0], seg_max_h[0], 1.6);
                snake_cross_section(jx - 2.0, seg_half_w[1] + 0.5, jh + 1.0, 1.2);
                translate([jx, 0, 0])
                    cylinder(r = get_cup_r(j) + 1.6, h = jh);
            }

            // Sculpted Supraocular Brow Ridges (left & right)
            for (side = [-1, 1]) {
                translate([-62.5, side * 8.6, 14.2])
                    rotate([side * 12, -14, -side * 16])
                        scale([4.8, 2.2, 1.6])
                            cylinder(r1 = 1.0, r2 = 0.4, h = 1.0, $fn = 24);
            }

            // Sculpted Parietal Head Crown Shield (top of cranium)
            translate([-55.5, 0, seg_max_h[0] - 0.8])
                scale([6.5, 4.8, 1.2])
                    cylinder(r1 = 1.0, r2 = 0.45, h = 1.0, $fn = 6);

            // Convex Eyeballs inside the recessed eye sockets
            for (side = [-1, 1]) {
                translate([-63.5, side * 9.5, 11.2])
                    rotate([0, 10, side * 18])
                        scale([1.25, 0.85, 1.10])
                            sphere(r = 2.1, $fn = 32);
            }
        }

        // --- Subtracted Features on Head ---
        // 1. Recessed Eye Sockets (angled upward at >= 50 deg so 100% self-supporting)
        for (side = [-1, 1]) {
            translate([-63.5, side * 10.6, 11.3])
                rotate([0, 10, side * 18])
                    scale([1.35, 1.0, 1.15])
                        sphere(r = 2.55, $fn = 32);

            // Vertical Slit Pupil on each eyeball
            translate([-63.5, side * 10.9, 11.2])
                rotate([0, 10, side * 18])
                    rotate([0, 0, 45])
                        cube([0.65, 0.65, 3.6], center = true);
        }

        // 2. Nostril Pits near snout tip
        for (side = [-1, 1]) {
            translate([-71.2, side * 4.8, 9.6])
                rotate([side * 25, -25, 0])
                    cylinder(r1 = 0.5, r2 = 1.1, h = 2.2, center = true, $fn = 24);
        }

        // 3. Self-supporting 45-deg V-shaped Mouth / Jaw Line Groove along snout & cheeks
        for (side = [-1, 1]) {
            hull() {
                translate([snout_tip_x + 0.5, side * 4.4, 4.2])
                    rotate([45, 0, 0])
                        cube([1.2, 1.1, 1.1], center = true);
                translate([-64.0, side * 11.4, 5.2])
                    rotate([45, 0, 0])
                        cube([1.2, 1.3, 1.3], center = true);
            }
            hull() {
                translate([-64.0, side * 11.4, 5.2])
                    rotate([45, 0, 0])
                        cube([1.2, 1.3, 1.3], center = true);
                translate([-55.0, side * (seg_half_w[0] - 0.2), 6.2])
                    rotate([45, 0, 0])
                        cube([1.2, 1.1, 1.1], center = true);
            }
        }
        // Front mouth seam at snout tip
        hull() {
            for (side = [-1, 1]) {
                translate([snout_tip_x + 0.8, side * 4.4, 4.2])
                    rotate([0, 45, 0])
                        cube([1.1, 1.0, 1.1], center = true);
            }
        }

        // 4. Subtract Rear Joint 1 Cup Cutout
        anterior_cup_cutout(j);

        // 5. Ensure flat bottom on Z = 0
        translate([-90, -30, -10])
            cube([180, 60, 10]);
    }

    // Add Joint 1 Spool Pin + Neck at the rear of the Head
    joint_pin_and_neck(j);
}

